const PAD = 50;
const SZE = 4 * 7;

function setup() {
  const maxX = ~~((windowWidth - PAD - PAD) / SZE) * SZE + PAD + PAD;
  const maxY = ~~((windowHeight - PAD - PAD) / SZE) * SZE + PAD + PAD;
  createCanvas(maxX, maxY);
  describe("grid of horizontal lines based on noise");
  frameRate(4);

  stroke("black");
  strokeWeight(2);
}

function draw() {
  background("beige");

  for (let y = PAD + SZE / 2; y <= height - SZE / 2 - PAD; y += SZE) {
    for (let x = PAD + SZE / 2; x <= width - SZE / 2 - PAD; x += SZE) {
      drawShape(x, y, SZE);
    }
  }
}

function drawShape(x, y, s) {
  push();
  translate(x, y);
  noStroke();
  fill("rgb(48,48,80)");

  const s2 = s / 2;
  const s4 = s / 4;
  const n = noise(x, y, frameCount * 0.1);
  if (n < 0.5) {
    // nothing
  } else if (n < 0.6) {
    crect(-s2, -s2, s, s4);
  } else if (n < 0.7) {
    crect(-s2, 0, s, s4);
  } else {
    crect(-s2, -s2, s, s4);
    crect(-s2, 0, s, s4);
  }

  pop();
}

function mousePressed() {
  if (mouseButton === LEFT) setup();
}

